// pinocchio::scalar_cast is a pure, header-only template that converts From->To via ScalarCast or static_cast.
// There are no persistent objects; we generate various numeric From values and cast to multiple To types.
// We avoid non-castable types to respect the requirement that ScalarCast<To,From>::cast(value) be valid.

int si = *FUZZ_PARAM(int);
unsigned int ui = *FUZZ_PARAM(unsigned int);
long long sll = *FUZZ_PARAM(long long);
double d = *FUZZ_PARAM(double);
float f = *FUZZ_PARAM(float);
bool b = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0;

// From: int
(void)pinocchio::scalar_cast<int>(si);
(void)pinocchio::scalar_cast<long long>(si);
(void)pinocchio::scalar_cast<float>(si);
(void)pinocchio::scalar_cast<double>(si);

// From: unsigned int
(void)pinocchio::scalar_cast<int>(ui);
(void)pinocchio::scalar_cast<unsigned int>(ui);
(void)pinocchio::scalar_cast<double>(ui);

// From: long long
(void)pinocchio::scalar_cast<int>(sll);
(void)pinocchio::scalar_cast<double>(sll);

// From: double
(void)pinocchio::scalar_cast<int>(d);
(void)pinocchio::scalar_cast<float>(d);
(void)pinocchio::scalar_cast<double>(d);

// From: float
(void)pinocchio::scalar_cast<int>(f);
(void)pinocchio::scalar_cast<double>(f);
(void)pinocchio::scalar_cast<float>(f);

// From: bool
(void)pinocchio::scalar_cast<int>(b);
(void)pinocchio::scalar_cast<double>(b);
(void)pinocchio::scalar_cast<bool>(b);

// No attributes or error conditions to enforce; this stub simply exercises valid conversions.
